(function() {
    'use strict';

    const isEventFound = window.__IS_EVENT_FOUND__ || false;

    function getAntiforgeryToken() {
        const el = document.querySelector('#antiforgeryForm input[name="__RequestVerificationToken"]');
        return el ? el.value : "";
    }

    function initializeUploadMode(config) {
        const { maxPhotos, eventCode } = config;
        const photos = [];
        const elements = {
            dropzone: document.getElementById("dropzone"),
            fileInput: document.getElementById("fileInput"),
            photoGrid: document.getElementById("photoGrid"),
            selectionCount: document.getElementById("selectionCount"),
            statusBar: document.getElementById("statusBar"),
            submitBtn: document.getElementById("submitBtn"),
            toast: document.getElementById("toast"),
            guestNameInput: document.getElementById("guestName"),
            uploadProgress: document.getElementById("uploadProgress"),
            progressFill: document.getElementById("progressFill"),
            progressText: document.getElementById("progressText")
        };

        function setToast(message, type) {
            elements.toast.textContent = message || "";
            elements.toast.className = "toast-message" + (type ? " " + type : "");
        }

        function updateCount() {
            elements.selectionCount.textContent = photos.length + " of " + maxPhotos + " photos";
            elements.statusBar.classList.toggle("limit-reached", photos.length >= maxPhotos);
            elements.submitBtn.hidden = photos.length === 0;
        }

        function addPhoto(file) {
            if (photos.length >= maxPhotos) return;

            const previewUrl = URL.createObjectURL(file);
            const tile = createPhotoTile(previewUrl);
            const entry = { tile, file, previewUrl };
            
            photos.push(entry);
            updateCount();

            tile.querySelector('.delete-tile-btn').addEventListener('click', () => removePhoto(entry));
        }

        function createPhotoTile(previewUrl) {
            const tile = document.createElement("div");
            tile.className = "photo-tile";
            tile.innerHTML = `
                <img src="${previewUrl}" alt="Selected photo preview" />
                <button type="button" class="delete-tile-btn" aria-label="Remove photo">&times;</button>
            `;
            elements.photoGrid.appendChild(tile);
            return tile;
        }

        function removePhoto(entry) {
            const index = photos.indexOf(entry);
            if (index === -1) return;

            URL.revokeObjectURL(entry.previewUrl);
            entry.tile.remove();
            photos.splice(index, 1);
            updateCount();
        }

        function handleFiles(fileList) {
            const files = Array.from(fileList).filter(f => f.type.startsWith("image/"));
            if (files.length === 0) return;

            const remaining = maxPhotos - photos.length;
            if (remaining <= 0) {
                setToast("You can upload up to " + maxPhotos + " photos at a time.", "error");
                return;
            }

            if (files.length > remaining) {
                setToast("Only " + remaining + " more photo(s) can be added to this batch.", "error");
            }

            files.slice(0, remaining).forEach(file => addPhoto(file));
        }

        function setupDropzone() {
            const dropzone = elements.dropzone;
            
            dropzone.addEventListener("click", () => elements.fileInput.click());
            elements.fileInput.addEventListener("change", (e) => {
                handleFiles(e.target.files);
                elements.fileInput.value = "";
            });

            ['dragenter', 'dragover'].forEach(evt => {
                dropzone.addEventListener(evt, (e) => {
                    e.preventDefault();
                    dropzone.classList.add("drag-over");
                });
            });

            ['dragleave', 'drop'].forEach(evt => {
                dropzone.addEventListener(evt, (e) => {
                    e.preventDefault();
                    dropzone.classList.remove("drag-over");
                });
            });

            dropzone.addEventListener("drop", (e) => {
                if (e.dataTransfer?.files) handleFiles(e.dataTransfer.files);
            });
        }

        async function uploadPhotos() {
            if (photos.length === 0) return;

            const guestName = elements.guestNameInput.value.trim() || "Guest";
            
            elements.submitBtn.disabled = true;
            elements.submitBtn.classList.add("loading");
            elements.uploadProgress.style.display = "block";

            try {
                const photoData = [];
                for (let i = 0; i < photos.length; i++) {
                    elements.progressText.textContent = `Uploading photo ${i + 1} of ${photos.length}...`;
                    elements.progressFill.style.width = `${((i + 1) / photos.length) * 100}%`;
                    const base64 = await fileToBase64(photos[i].file);
                    photoData.push(base64);
                }

                const response = await fetch("/Guest/GuestUpload?handler=Upload", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "RequestVerificationToken": getAntiforgeryToken()
                    },
                    body: JSON.stringify({ eventCode, guestName, photoData })
                });

                const result = await response.json();

                if (result.success) {
                    setToast("Photos uploaded successfully!", "success");
                    // Reload so Recent Submissions picks up newly-approved photos
                    // and the guest can start another batch of up to maxPhotos.
                    setTimeout(() => {
                        window.location.href = `/Guest/GuestUpload?code=${eventCode}`;
                    }, 1500);
                } else {
                    setToast(result.message || "Upload failed. Please try again.", "error");
                    resetUploadState();
                }
            } catch (error) {
                console.error(error);
                setToast("Upload failed. Please check your connection.", "error");
                resetUploadState();
            }
        }

        function resetUploadState() {
            elements.submitBtn.disabled = false;
            elements.submitBtn.classList.remove("loading");
            elements.uploadProgress.style.display = "none";
        }

        function fileToBase64(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        elements.submitBtn.addEventListener("click", uploadPhotos);
        setupDropzone();
        updateCount();
    }

    function initializeScannerMode() {
        let cameraStream = null;
        let cameraLoopId = null;
        let isProcessing = false;

        const elements = {
            scanCameraBtn: document.getElementById("scanCameraBtn"),
            cancelCameraBtn: document.getElementById("cancelCameraBtn"),
            cameraContainer: document.getElementById("cameraContainer"),
            cameraVideo: document.getElementById("cameraVideo"),
            cameraCanvas: document.getElementById("cameraCanvas"),
            eventCodeInput: document.getElementById("eventCodeInput"),
            manualEntryBtn: document.getElementById("manualEntryBtn"),
            statusMsg: document.getElementById("statusMsg")
        };

        function setStatus(message, type) {
            elements.statusMsg.textContent = message || "";
            elements.statusMsg.className = "toast-message" + (type ? " " + type : "");
        }

        async function submitQrData(qrData) {
            if (isProcessing) return;
            isProcessing = true;
            setStatus("Checking QR code…");

            try {
                const response = await fetch("/Guest/GuestUpload?handler=Scan", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "RequestVerificationToken": getAntiforgeryToken()
                    },
                    body: JSON.stringify({ qrData })
                });

                const result = await response.json();

                if (result.success && result.redirectUrl) {
                    setStatus("Event found! Directing to upload...", "success");
                    stopCamera();
                    window.location.href = result.redirectUrl;
                } else {
                    setStatus(result.message || "Invalid QR code.", "error");
                    isProcessing = false;
                }
            } catch (err) {
                setStatus("Something went wrong.", "error");
                isProcessing = false;
            }
        }

        async function lookupEvent(code) {
            setStatus("Looking up event…");

            try {
                const response = await fetch("/Guest/GuestUpload?handler=Lookup", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "RequestVerificationToken": getAntiforgeryToken()
                    },
                    body: JSON.stringify({ eventCode: code })
                });

                const result = await response.json();

                if (result.success && result.redirectUrl) {
                    window.location.href = result.redirectUrl;
                } else {
                    setStatus(result.message || "Event not found.", "error");
                }
            } catch (err) {
                setStatus("Something went wrong.", "error");
            }
        }

        async function startCamera() {
            elements.cameraContainer.classList.add("is-active");
            elements.scanCameraBtn.style.display = "none";

            try {
                cameraStream = await navigator.mediaDevices.getUserMedia({ 
                    video: { facingMode: "environment" } 
                });
                elements.cameraVideo.srcObject = cameraStream;
                await elements.cameraVideo.play();
                requestAnimationFrame(scanFrame);
            } catch (err) {
                setStatus("Couldn't access the camera.", "error");
                stopCamera();
            }
        }

        function stopCamera() {
            if (cameraLoopId) cancelAnimationFrame(cameraLoopId);
            if (cameraStream) cameraStream.getTracks().forEach(track => track.stop());
            elements.cameraVideo.srcObject = null;
            elements.cameraContainer.classList.remove("is-active");
            elements.scanCameraBtn.style.display = "";
        }

        function scanFrame() {
            if (!cameraStream || isProcessing) return;

            if (elements.cameraVideo.readyState === elements.cameraVideo.HAVE_ENOUGH_DATA) {
                const ctx = elements.cameraCanvas.getContext("2d");
                elements.cameraCanvas.width = elements.cameraVideo.videoWidth;
                elements.cameraCanvas.height = elements.cameraVideo.videoHeight;
                ctx.drawImage(elements.cameraVideo, 0, 0, elements.cameraCanvas.width, elements.cameraCanvas.height);

                const imageData = ctx.getImageData(0, 0, elements.cameraCanvas.width, elements.cameraCanvas.height);
                const code = window.jsQR(imageData.data, imageData.width, imageData.height);

                if (code?.data) {
                    submitQrData(code.data);
                    return;
                }
            }
            cameraLoopId = requestAnimationFrame(scanFrame);
        }

        // Event listeners
        elements.scanCameraBtn.addEventListener("click", startCamera);
        elements.cancelCameraBtn.addEventListener("click", stopCamera);
        elements.manualEntryBtn.addEventListener("click", () => {
            const code = elements.eventCodeInput.value.trim();
            if (!code) {
                setStatus("Please enter an event code.", "error");
                return;
            }
            lookupEvent(code);
        });
    }

    function initializeRecentSubmissions() {
        const grid = document.getElementById("recentGrid");
        if (!grid) return;

        const cards = Array.from(grid.querySelectorAll(".recent-card"));
        const photos = cards.map(card => ({
            url: card.dataset.photoUrl,
            author: card.dataset.photoAuthor,
            el: card
        }));

        const selectToggleBtn = document.getElementById("selectToggleBtn");
        const saveBar = document.getElementById("saveBar");
        const saveCount = document.getElementById("saveCount");
        const saveSelectedBtn = document.getElementById("saveSelectedBtn");

        const lightbox = document.getElementById("lightbox");
        const lightboxImg = document.getElementById("lightboxImg");
        const lightboxClose = document.getElementById("lightboxClose");
        const lightboxPrev = document.getElementById("lightboxPrev");
        const lightboxNext = document.getElementById("lightboxNext");
        const lightboxSave = document.getElementById("lightboxSave");

        let selectionMode = false;
        const selected = new Set();
        let currentIndex = 0;

        function updateSaveBar() {
            saveCount.textContent = selected.size + " selected";
            saveBar.hidden = selected.size === 0;
        }

        function setSelectionMode(on) {
            selectionMode = on;
            grid.classList.toggle("selection-mode", on);
            selectToggleBtn.textContent = on ? "Cancel" : "Select";
            if (!on) {
                selected.clear();
                cards.forEach(card => card.classList.remove("selected"));
                updateSaveBar();
            }
        }

        function toggleSelected(index) {
            const card = photos[index].el;
            if (selected.has(index)) {
                selected.delete(index);
                card.classList.remove("selected");
            } else {
                selected.add(index);
                card.classList.add("selected");
            }
            updateSaveBar();
        }

        function showAt(index) {
            currentIndex = (index + photos.length) % photos.length;
            lightboxImg.src = photos[currentIndex].url;
            lightboxImg.alt = "Photo by " + photos[currentIndex].author;
        }

        function openLightbox(index) {
            showAt(index);
            lightbox.hidden = false;
            document.body.style.overflow = "hidden";
        }

        function closeLightbox() {
            lightbox.hidden = true;
            lightboxImg.src = "";
            document.body.style.overflow = "";
        }

        function extensionFromMime(mime) {
            if (mime && mime.includes("png")) return "png";
            if (mime && mime.includes("webp")) return "webp";
            if (mime && mime.includes("gif")) return "gif";
            return "jpg";
        }

        async function downloadPhoto(url, index) {
            try {
                const response = await fetch(url, { mode: "cors" });
                const blob = await response.blob();
                const objectUrl = URL.createObjectURL(blob);
                const link = document.createElement("a");
                link.href = objectUrl;
                link.download = `qremember-photo-${index + 1}.${extensionFromMime(blob.type)}`;
                document.body.appendChild(link);
                link.click();
                link.remove();
                URL.revokeObjectURL(objectUrl);
            } catch (err) {
                // Cross-origin fetch failed (e.g. no CORS header) — fall back to opening
                // the photo in a new tab so the guest can save it manually.
                window.open(url, "_blank");
            }
        }

        selectToggleBtn.addEventListener("click", () => setSelectionMode(!selectionMode));

        cards.forEach((card, index) => {
            card.addEventListener("click", () => {
                if (selectionMode) {
                    toggleSelected(index);
                } else {
                    openLightbox(index);
                }
            });
        });

        lightboxClose.addEventListener("click", closeLightbox);
        lightboxPrev.addEventListener("click", () => showAt(currentIndex - 1));
        lightboxNext.addEventListener("click", () => showAt(currentIndex + 1));
        lightbox.addEventListener("click", (e) => {
            if (e.target === lightbox) closeLightbox();
        });
        document.addEventListener("keydown", (e) => {
            if (lightbox.hidden) return;
            if (e.key === "Escape") closeLightbox();
            if (e.key === "ArrowLeft") showAt(currentIndex - 1);
            if (e.key === "ArrowRight") showAt(currentIndex + 1);
        });

        lightboxSave.addEventListener("click", () => {
            downloadPhoto(photos[currentIndex].url, currentIndex);
        });

        saveSelectedBtn.addEventListener("click", async () => {
            saveSelectedBtn.disabled = true;
            const indices = Array.from(selected);
            for (const index of indices) {
                await downloadPhoto(photos[index].url, index);
                await new Promise(resolve => setTimeout(resolve, 250));
            }
            saveSelectedBtn.disabled = false;
            setSelectionMode(false);
        });
    }

    // Initialize based on mode
    if (isEventFound) {
        initializeUploadMode({
            maxPhotos: window.__MAX_PHOTOS__ || 10,
            eventCode: window.__EVENT_CODE__ || ''
        });
    } else {
        initializeScannerMode();
    }

    initializeRecentSubmissions();

})();